mkdir -p /tmp/s && cat > /tmp/s/a.py <<'E'
import ast,sys,glob,os
for f in sorted(glob.glob('*.py')):
    m=f[:-3]; t=ast.parse(open(f).read())
    def visit(n,pre):
        for c in ast.iter_child_nodes(n):
            if isinstance(c,ast.ClassDef): visit(c,pre+[c.name])
            elif isinstance(c,(ast.FunctionDef,ast.AsyncFunctionDef)):
                r=ast.unparse(c.returns) if c.returns else '?'
                rets=[x for x in ast.walk(c) if isinstance(x,ast.Return)]
                hasval=any(x.value is not None for x in rets)
                if 'None' in r and r!='None' or (r=='?' and hasval):
                    print('.'.join([m]+pre+[c.name]),'->',r)
                visit(c,pre+[c.name]) if False else None
    visit(t,[])
E
.venv/bin/python -I /tmp/s/a.py 2>/dev/null || python3 -I /tmp/s/a.py
